"""Load JSON config from disk, falling back to defaults if the file is absent."""

import json
import logging
from pathlib import Path
from typing import Any

logger = logging.getLogger(__name__)

DEFAULT_CONFIG: dict[str, Any] = {
    "host": "localhost",
    "port": 8080,
    "debug": False,
    "log_level": "INFO",
    "max_connections": 100,
}


def load_config(path: str | Path) -> dict[str, Any]:
    path = Path(path)

    if not path.exists():
        logger.warning("Config file %s not found, using defaults", path)
        return dict(DEFAULT_CONFIG)

    try:
        with path.open("r", encoding="utf-8") as f:
            data = json.load(f)
    except json.JSONDecodeError as e:
        logger.error("Config file %s contains invalid JSON: %s", path, e)
        return dict(DEFAULT_CONFIG)

    if not isinstance(data, dict):
        logger.error("Config file %s must contain a JSON object, got %s", path, type(data).__name__)
        return dict(DEFAULT_CONFIG)

    config = dict(DEFAULT_CONFIG)
    config.update(data)
    return config


def save_config(path: str | Path, config: dict[str, Any]) -> None:
    path = Path(path)
    with path.open("w", encoding="utf-8") as f:
        json.dump(config, f, indent=2)
